const parserFromTransform = typeof transformModule.parser === 'string'
  ? getParser(transformModule.parser)
  : transformModule.parser;

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function(line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function sendIPC(data) {
  const payload = JSON.stringify({ _jscodeshift_ipc: 1, ...data });
  process.stdout.write(payload + '\n');
}

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false,
});

rl.on('line', async (line) => {
  if (!line || !line.trim()) return;
  let msg;
  try {
    msg = JSON.parse(line);
  } catch (e) {
    return;
  }
  if (msg.action === 'exit') {
    process.exit(0);
  }
