    const options = msg.options || {};

    if (files.length === 0) {
      process.exit(0);
    }

    for (const file of files) {
      let source;
      try {
        source = fs.readFileSync(file, 'utf8');
      } catch (err) {
        sendIPC({
          action: 'status',
          status: 'error',
          file: file,
          msg: file + ' File error: ' + err.message,
        });
        continue;
