      const parser = parserFromTransform || (options.parser ? getParser(options.parser, options.parserConfig) : null);
      const jscodeshift = parser ? jscodeshiftCore.withParser(parser) : jscodeshiftCore;

      const api = {
        j: jscodeshift,
        jscodeshift: jscodeshift,
        stats: options.dry ? (name, quantity) => sendIPC({ action: 'update', name, quantity: typeof quantity !== 'number' ? 1 : quantity }) : () => {},
        report: (reportMsg) => sendIPC({ action: 'report', file, msg: String(reportMsg) }),
      };

      try {
        const out = await transform({ path: file, source }, api, options);
        if (out === undefined || out === null) {
          sendIPC({
            action: 'status',
            status: 'skip',
            file: file,
            msg: file,
          });
        } else if (out === source) {
          sendIPC({
            action: 'status',
            status: 'nochange',
            file: file,
            msg: file,
          });
        } else {
          if (options.print) {
            console.log(out);
          }
          if (!options.dry) {
            try {
              writeFileAtomic.sync(file, out);
              sendIPC({
                action: 'status',
                status: 'ok',
                file: file,
                msg: file,
              });
            } catch (writeErr) {
              sendIPC({
                action: 'status',
                status: 'error',
                file: file,
                msg: file + ' File writer error: ' + writeErr.message,
              });
            }
          } else {
            sendIPC({
              action: 'status',
              status: 'ok',
              file: file,
              msg: file,
            });
          }
        }
      } catch (err) {
        const trimmed = trimStackTrace(err.stack);
        sendIPC({
          action: 'status',
          status: 'error',
          file: file,
          msg: file + ' Transformation error (' + (err.message || '').replace(/\n/g, ' ') + ')\n' + trimmed,
        });
      }
    }

    sendIPC({ action: 'free' });
  }
});
