{"command":"create","path":"/workspace/src/package_utils.rs","file_text":"use std::fs;
use std::path::{Path, PathBuf};
use serde_json::Value;

fn find_package_version(name: &str) -> Option<String> {
    let cwd = std::env::current_dir().ok()?;
    let mut search_dirs = vec![
        cwd.clone(),
        cwd.join("codebase"),
    ];

    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            search_dirs.push(parent.to_path_buf());
            if let Some(p2) = parent.parent() {
                search_dirs.push(p2.to_path_buf());
                if let Some(p3) = p2.parent() {
                    search_dirs.push(p3.to_path_buf());
                }
            }
        }
    }

    for base in search_dirs {
        let direct = base.join("node_modules").join(name).join("package.json");
        if direct.exists() {
            if let Ok(content) = fs::read_to_string(&direct) {
                if let Ok(json) = serde_json::from_str::<Value>(&content) {
                    if let Some(v) = json.get("version").and_then(|v| v.as_str()) {
                        return Some(v.to_string());
                    }
                }
            }
        }
    }

    None
}

pub fn get_version_text() -> String {
    let jscodeshift_ver = "17.4.0";
    let babel_ver = find_package_version("@babel/core").unwrap_or_else(|| "7.29.6".to_string());
    let babylon_ver = find_package_version("@babel/parser").unwrap_or_else(|| "7.29.7".to_string());
    let flow_ver = find_package_version("flow-parser").unwrap_or_else(|| "0.237.2".to_string());
    let recast_ver = find_package_version("recast").unwrap_or_else(|| "0.23.11".to_string());

    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        jscodeshift_ver, babel_ver, babylon_ver, flow_ver, recast_ver
    )
}
"}

