pub fn format_option(opt: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    let flag_prefix = if opt.flag { "(no-)" } else { "" };
    text.push_str(&format!("--{}{}", flag_prefix, opt.full));
    if let Some(choices) = &opt.choices {
        text.push_str(&format!("={}", choices.join("|")));
    } else if let Some(metavar) = &opt.metavar {
        text.push_str(&format!("={}", metavar));
    }
    if opt.list {
        text.push_str(" ...");
    }
    if opt.default_help.is_some() || opt.default_val.is_some() || opt.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(help) = &opt.help {
            text.push_str(help);
        }
        if opt.default_help.is_some() || opt.default_val.is_some() {
            if opt.help.is_some() {
                text.push('\n');
            }
            let def_val = opt
                .default_help
                .as_deref()
                .unwrap_or_else(|| opt.default_val.as_deref().unwrap_or(""));
            text.push_str(&format!("{}(default: {})", " ".repeat(text_length), def_val));
        }
    }
    text
}

pub fn get_help_text() -> String {
    let mut defs = get_option_defs();
    defs.sort_by_key(|d| d.display_index);

    let opts_text = defs.iter().map(format_option).collect::<Vec<_>>().join("\n");

    format!(
        "Usage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        opts_text
    )
}

#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub positional_arguments: Vec<String>,
    pub options: Map<String, Value>,
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: usize,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<Value>,
    pub fail_on_error: bool,
    pub stdin: bool,
}

pub enum ParseResult {
    Success(ParsedArgs),
    Help(String),
    Version(String),
    Error { message: String, exit_code: i32 },
}

fn is_option(val: &str) -> bool {
    val.starts_with('-')
}

fn parse_json_or_string(val: &str) -> Value {
    if let Ok(num) = val.parse::<i64>() {
        return Value::Number(num.into());
    }
    if let Ok(num) = val.parse::<f64>() {
        if let Some(n) = serde_json::Number::from_f64(num) {
            return Value::Number(n);
        }
    }
    if val == "true" {
        return Value::Bool(true);
    }
    if val == "false" {
        return Value::Bool(false);
    }
    if val == "null" {
        return Value::Null;
    }
    if let Ok(v) = serde_json::from_str::<Value>(val) {
        return v;
    }
    Value::String(val.to_string())
}

pub fn parse_cli_args(args: &[String]) -> ParseResult {
    let defs = get_option_defs();
    let mut prepared_by_flag: HashMap<String, OptionDef> = HashMap::new();

    for def in &defs {
        prepared_by_flag.insert(format!("--{}", def.full), def.clone());
        if let Some(abbr) = def.abbr {
            prepared_by_flag.insert(format!("-{}", abbr), def.clone());
        }
        if def.flag {
            prepared_by_flag.insert(format!("--no-{}", def.full), def.clone());
        }
    }

    let mut parsed_options: Map<String, Value> = Map::new();
    let mut positional_arguments: Vec<String> = Vec::new();

    // Set defaults
    for def in &defs {
        if let Some(def_val) = def.default_val {
            if def.flag {
                parsed_options.insert(def.key.to_string(), Value::Bool(def_val == "true"));
            } else if def.key == "verbose" {
                parsed_options.insert(def.key.to_string(), json!(0));
            } else {
                parsed_options.insert(def.key.to_string(), Value::String(def_val.to_string()));
            }
        } else if def.list {
            parsed_options.insert(def.key.to_string(), Value::Array(Vec::new()));
        }
    }

    let missing_marker = "__MISSING_VALUE__";
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let (option_name, mut value) = if let Some(idx) = arg.find('=') {
                (arg[..idx].to_string(), Some(arg[idx + 1..].to_string()))
            } else {
                (arg.to_string(), None)
            };

            if option_name == "-h" || option_name == "--help" {
                return ParseResult::Help(get_help_text());
            }
            if option_name == "--version" {
                return ParseResult::Version(crate::package_utils::get_version_text());
            }

            if let Some(def) = prepared_by_flag.get(&option_name).cloned() {
                if def.flag {
                    let bool_val = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(v) = value {
                        v == "1"
                    } else {
                        true
                    };
                    parsed_options.insert(def.key.to_string(), Value::Bool(bool_val));
                } else {
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }

                    if let Some(val_str) = value {
                        let processed_val = if def.key == "verbose" || def.key == "cpus" {
                            if let Ok(n) = val_str.parse::<i64>() {
                                Value::Number(n.into())
                            } else {
                                Value::String(val_str)
                            }
                        } else if def.key == "parserConfig" {
                            match fs::read_to_string(&val_str) {
                                Ok(content) => match serde_json::from_str::<Value>(&content) {
                                    Ok(json_val) => json_val,
                                    Err(err) => {
                                        return ParseResult::Error {
                                            message: format!("Error reading/parsing parser-config {}: {}", val_str, err),
                                            exit_code: 1,
                                        };
                                    }
                                },
                                Err(err) => {
                                    return ParseResult::Error {
                                        message: format!("Error reading parser-config file {}: {}", val_str, err),
                                        exit_code: 1,
                                    };
                                }
                            }
                        } else {
                            Value::String(val_str)
                        };

                        if def.list {
                            if let Some(arr) = parsed_options.get_mut(def.key).and_then(|v| v.as_array_mut()) {
                                arr.push(processed_val);
                            } else {
                                parsed_options.insert(def.key.to_string(), Value::Array(vec![processed_val]));
                            }
                        } else {
                            parsed_options.insert(def.key.to_string(), processed_val);
                        }
                    } else {
                        parsed_options.insert(def.key.to_string(), Value::String(missing_marker.to_string()));
                    }
                }
            } else {
                // Unknown options passed along
                let real_option_name = option_name
                    .trim_start_matches("--")
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();

                let is_flag = !parsed_options.contains_key(&real_option_name)
                    && value.is_none()
                    && (i + 1 >= args.len() || is_option(&args[i + 1]));

                if is_flag {
                    let bool_val = !option_name.starts_with("--no-");
                    parsed_options.insert(real_option_name, Value::Bool(bool_val));
                } else {
                    if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }

                    if let Some(val_str) = value {
                        let parsed_val = parse_json_or_string(&val_str);
                        if let Some(existing) = parsed_options.get(&real_option_name) {
                            let mut arr = match existing {
                                Value::Array(a) => a.clone(),
                                Value::Bool(true) => Vec::new(),
                                other => vec![other.clone()],
                            };
                            arr.push(parsed_val);
                            parsed_options.insert(real_option_name, Value::Array(arr));
                        } else {
                            parsed_options.insert(real_option_name, parsed_val);
                        }
                    } else {
                        parsed_options.insert(real_option_name, Value::String(missing_marker.to_string()));
                    }
                }
            }
        } else {
            positional_arguments.push(arg.clone());
        }
        i += 1;
    }

    // Check missing values
    for def in &defs {
        if let Some(v) = parsed_options.get(def.key) {
            if v == missing_marker {
                return ParseResult::Error {
                    message: format!(
                        "Missing value: --{} requires a value\n\n---\n\n{}",
                        def.full,
                        get_help_text()
                    ),
                    exit_code: 1,
                };
            }
        }
    }

    // Check choices
    let mut validation_errors = Vec::new();
    for def in &defs {
        if let Some(choices) = &def.choices {
            if let Some(val) = parsed_options.get(def.key) {
                let val_str = match val {
                    Value::String(s) => s.clone(),
                    Value::Number(n) => n.to_string(),
                    _ => val.to_string(),
                };
                if !choices.contains(&val_str.as_str()) {
                    validation_errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        def.full,
                        choices.join(",")
                    ));
                }
            }
        }
    }

    if !validation_errors.is_empty() {
        return ParseResult::Error {
            message: format!("{}\n\n---\n\n{}", validation_errors.join("\n"), get_help_text()),
            exit_code: 1,
        };
    }

    let stdin = parsed_options
        .get("stdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if positional_arguments.is_empty() && !stdin {
        return ParseResult::Error {
            message: format!(
                "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
                get_help_text()
            ),
            exit_code: 1,
        };
    }

    let transform = parsed_options
        .get("transform")
        .and_then(|v| v.as_str())
        .unwrap_or("./transform.js")
        .to_string();

    let cpus = parsed_options
        .get("cpus")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);

    let verbose = parsed_options
        .get("verbose")
        .and_then(|v| {
            if let Some(n) = v.as_u64() {
                Some(n as usize)
            } else if let Some(s) = v.as_str() {
                s.parse::<usize>().ok()
            } else {
                None
            }
        })
        .unwrap_or(0);

    let dry = parsed_options
        .get("dry")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let print = parsed_options
        .get("print")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let babel = parsed_options
        .get("babel")
        .and_then(|v| v.as_bool())
        .unwrap_or(true);

    let extensions = parsed_options
        .get("extensions")
        .and_then(|v| v.as_str())
        .unwrap_or("cjs,es,es6,js,jsx,mjs,ts,tsx")
        .to_string();

    let ignore_pattern = parsed_options
        .get("ignorePattern")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default();

    let ignore_config = parsed_options
        .get("ignoreConfig")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default();

    let gitignore = parsed_options
        .get("gitignore")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let run_in_band = parsed_options
        .get("runInBand")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let silent = parsed_options
        .get("silent")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let parser = parsed_options
        .get("parser")
        .and_then(|v| v.as_str())
        .unwrap_or("babel")
        .to_string();

    let parser_config = parsed_options.get("parserConfig").cloned();

    let fail_on_error = parsed_options
        .get("failOnError")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    ParseResult::Success(ParsedArgs {
        positional_arguments,
        options: parsed_options,
        transform,
        cpus,
        verbose,
        dry,
        print,
        babel,
        extensions,
        ignore_pattern,
        ignore_config,
        gitignore,
        run_in_band,
        silent,
        parser,
        parser_config,
        fail_on_error,
        stdin,
    })
}
