{"path":"/workspace/src/ignore.rs","command":"create","file_text":"use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
use std::fs;
use std::path::Path;

#[derive(Clone, Default)]
pub struct IgnoreManager {
    patterns: Vec<String>,
}

impl IgnoreManager {
    pub fn new() -> Self {
        Self {
            patterns: Vec::new(),
        }
    }

    pub fn add_pattern(&mut self, val: &str) {
        let trimmed = val.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            return;
        }

        if !trimmed.contains('/') {
            self.patterns.push(format!("**/{}", trimmed));
            self.patterns.push(trimmed.to_string());
        } else if trimmed.ends_with('/') {
            self.patterns.push(format!("**/{}**", trimmed));
            self.patterns.push(format!("{}**", trimmed));
            self.patterns.push(trimmed.to_string());
        } else {
            self.patterns.push(trimmed.to_string());
        }
    }

    pub fn add_patterns<I, S>(&mut self, patterns: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for p in patterns {
            self.add_pattern(p.as_ref());
        }
    }

    pub fn add_from_file<P: AsRef<Path>>(&mut self, path: P) {
        let p = path.as_ref();
        if p.is_file() {
            if let Ok(content) = fs::read_to_string(p) {
                for line in content.lines() {
                    self.add_pattern(line);
                }
            }
        }
    }

    pub fn build_matcher(&self) -> Result<IgnoreMatcher, globset::Error> {
        let mut builder = GlobSetBuilder::new();
        for pat in &self.patterns {
            let glob = GlobBuilder::new(pat)
                .literal_separator(true)
                .backslash_escape(false)
                .build()?;
            builder.add(glob);
        }
        let set = builder.build()?;
        Ok(IgnoreMatcher { set, empty: self.patterns.is_empty() })
    }
}

pub struct IgnoreMatcher {
    set: GlobSet,
    empty: bool,
}

impl IgnoreMatcher {
    pub fn should_ignore(&self, path: &str) -> bool {
        if self.empty {
            return false;
        }

        let clean_path = path.replace('\\', "/");
        if self.set.is_match(&clean_path) {
            return true;
        }

        // Strip leading ./ or ../ or multiple
        let mut normalized = clean_path.as_str();
        while normalized.starts_with("./") || normalized.starts_with("../") {
            if normalized.starts_with("./") {
                normalized = &normalized[2..];
            } else if normalized.starts_with("../") {
                normalized = &normalized[3..];
            }
        }

        if normalized != clean_path && self.set.is_match(normalized) {
            return true;
        }

        false
    }
}
