{"path":"/workspace/src/file_discovery.rs","file_text":"use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use crate::ignore::IgnoreMatcher;

fn has_valid_extension(file_path: &str, extensions: &[String]) -> bool {
    if extensions.is_empty() {
        return true;
    }
    let p = Path::new(file_path);
    if let Some(ext) = p.extension().and_then(|s| s.to_str()) {
        let dot_ext = format!(".{}", ext);
        extensions.iter().any(|e| e == &dot_ext || e == ext)
    } else {
        false
    }
}

fn traverse_dir(
    dir_path: &str,
    matcher: &IgnoreMatcher,
    files_out: &mut Vec<String>,
) {
    let entries = match fs::read_dir(dir_path) {
        Ok(e) => e,
        Err(_) => return,
    };

    let mut paths = Vec::new();
    for entry in entries.flatten() {
        paths.push(entry.path());
    }
    paths.sort();

    for p in paths {
        let path_str = p.to_string_lossy().to_string();
        match fs::metadata(&p) {
            Err(_) => {
                let _ = writeln!(
                    std::io::stdout(),
                    "Skipping path \"{}\" which does not exist.",
                    path_str
                );
            }
            Ok(meta) => {
                if matcher.should_ignore(&path_str) {
                    continue;
                }
                if meta.is_dir() {
                    traverse_dir(&path_str, matcher, files_out);
                } else {
                    files_out.push(path_str);
                }
            }
        }
    }
}

pub fn get_all_files(
    paths: &[String],
    extensions_str: &str,
    matcher: &IgnoreMatcher,
) -> Vec<String> {
    let extensions: Vec<String> = if extensions_str.is_empty() {
        Vec::new()
    } else {
        extensions_str
            .split(',')
            .map(|ext| {
                let ext = ext.trim();
                if ext.starts_with('.') {
                    ext.to_string()
                } else {
                    format!(".{}", ext)
                }
            })
            .collect()
    };

    let mut result = Vec::new();

    for path in paths {
        let path_trimmed = path.trim();
        if path_trimmed.is_empty() {
            continue;
        }

        let p = Path::new(path_trimmed);
        match fs::symlink_metadata(p) {
            Err(_) => {
                let _ = writeln!(
                    std::io::stderr(),
                    "Skipping path {} which does not exist. ",
                    path_trimmed
                );
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut dir_collected = Vec::new();
                    traverse_dir(path_trimmed, matcher, &mut dir_collected);
                    for f in dir_collected {
                        if has_valid_extension(&f, &extensions) {
                            result.push(f);
                        }
                    }
                } else if !has_valid_extension(path_trimmed, &extensions)
                    || matcher.should_ignore(path_trimmed)
                {
                    // skipped
                } else {
                    result.push(path_trimmed.to_string());
                }
            }
        }
    }

    result
}
