{"file_text":"use std::io::Write;
use std::path::{Path, PathBuf};
use tempfile::{Builder, NamedTempFile};

pub struct FetchedTransform {
    pub path: PathBuf,
    pub _temp_file: Option<NamedTempFile>,
}

pub fn resolve_transform_path(transform: &str) -> Result<FetchedTransform, Box<dyn std::error::Error>> {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        let resp = ureq::get(transform).call()?;
        let mut reader = resp.into_reader();
        let mut body = Vec::new();
        std::io::copy(&mut reader, &mut body)?;

        let ext = Path::new(transform)
            .extension()
            .and_then(|s| s.to_str())
            .map(|s| format!(".{}", s))
            .unwrap_or_else(|| ".js".to_string());

        let mut temp_file = Builder::new()
            .prefix("jscodeshift")
            .suffix(&ext)
            .tempfile()?;

        temp_file.write_all(&body)?;
        temp_file.flush()?;

        let path = temp_file.path().to_path_buf();
        Ok(FetchedTransform {
            path,
            _temp_file: Some(temp_file),
        })
    } else {
        let abs_path = if Path::new(transform).is_absolute() {
            PathBuf::from(transform)
        } else {
            std::env::current_dir()?.join(transform)
        };

        Ok(FetchedTransform {
            path: abs_path,
            _temp_file: None,
        })
    }
}
