}

pub struct WorkerHandle {
    pub child: Child,
    pub stdin: ChildStdin,
    pub reader: BufReader<ChildStdout>,
}

fn find_bridge_script() -> PathBuf {
    if let Ok(env_path) = std::env::var("JSCODESHIFT_BRIDGE_PATH") {
        let p = PathBuf::from(env_path);
        if p.exists() {
            return p;
        }
    }

    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let candidates = [
        cwd.join("codebase/bridge/transform-host.js"),
        cwd.join("bridge/transform-host.js"),
        cwd.join("../codebase/bridge/transform-host.js"),
        cwd.join("../bridge/transform-host.js"),
        PathBuf::from("/workspace/codebase/bridge/transform-host.js"),
        PathBuf::from("/workspace/bridge/transform-host.js"),
    ];

    for candidate in &candidates {
        if candidate.exists() {
            return candidate.clone();
        }
    }

    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            let p1 = parent.join("codebase/bridge/transform-host.js");
            if p1.exists() {
                return p1;
            }
            let p2 = parent.join("bridge/transform-host.js");
            if p2.exists() {
                return p2;
            }
            if let Some(p_parent) = parent.parent() {
                let p3 = p_parent.join("codebase/bridge/transform-host.js");
                if p3.exists() {
                    return p3;
                }
                if let Some(p3_parent) = p_parent.parent() {
                    let p4 = p3_parent.join("codebase/bridge/transform-host.js");
                    if p4.exists() {
                        return p4;
                    }
                }
            }
        }
    }

    PathBuf::from("codebase/bridge/transform-host.js")
}

pub fn spawn_worker(transform_file: &Path, babel: bool) -> Result<WorkerHandle, std::io::Error> {
    let bridge_path = find_bridge_script();
    let babel_arg = if babel { "babel" } else { "no-babel" };

    let mut child = Command::new("node")
        .arg(&bridge_path)
        .arg(transform_file)
        .arg(babel_arg)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()?;

    let stdin = child.stdin.take().expect("Failed to open worker stdin");
    let stdout = child.stdout.take().expect("Failed to open worker stdout");
    let reader = BufReader::new(stdout);

    Ok(WorkerHandle {
        child,
        stdin,
        reader,
    })
}

impl WorkerHandle {
    pub fn send_chunk(&mut self, files: &[String], options: &Value) -> Result<(), std::io::Error> {
        let msg = serde_json::json!({
            "action": "run",
            "files": files,
            "options": options,
        });
        let line = serde_json::to_string(&msg)?;
        writeln!(self.stdin, "{}", line)?;
        self.stdin.flush()?;
        Ok(())
    }

    pub fn send_exit(&mut self) -> Result<(), std::io::Error> {
        let msg = serde_json::json!({
            "action": "exit"
        });
        let line = serde_json::to_string(&msg)?;
        let _ = writeln!(self.stdin, "{}", line);
        let _ = self.stdin.flush();
        Ok(())
    }
}
