struct CounterState {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
    stats: HashMap<String, i64>,
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn log_status(status: &str, msg: &str, verbose: usize) {
    let mut stdout = std::io::stdout();
    match status {
        "ok" => {
            if verbose >= 2 {
                let _ = write!(
                    stdout,
                    "\x1b[42m\x1b[37m OKK \x1b[39m\x1b[49m{}",
                    line_break(msg)
                );
                let _ = stdout.flush();
            }
        }
        "nochange" => {
            if verbose >= 1 {
                let _ = write!(
                    stdout,
                    "\x1b[43m\x1b[37m NOC \x1b[39m\x1b[49m{}",
                    line_break(msg)
                );
                let _ = stdout.flush();
            }
        }
        "skip" => {
            if verbose >= 1 {
                let _ = write!(
                    stdout,
                    "\x1b[43m\x1b[37m SKIP \x1b[39m\x1b[49m{}",
                    line_break(msg)
                );
                let _ = stdout.flush();
            }
        }
        "error" => {
            if verbose >= 0 {
                let _ = write!(
                    stdout,
                    "\x1b[41m\x1b[37m ERR \x1b[39m\x1b[49m{}",
                    line_break(msg)
                );
                let _ = stdout.flush();
            }
        }
        _ => {}
    }
}

fn log_report(file: &str, msg: &str) {
    let mut stdout = std::io::stdout();
    let _ = write!(
        stdout,
        "\x1b[44m\x1b[37m REP \x1b[39m\x1b[49m{} {}\n",
        file, msg
    );
    let _ = stdout.flush();
}

pub fn run(paths: &[String], args: &ParsedArgs) -> i32 {
    let start_time = Instant::now();

    let mut ignore_mgr = IgnoreManager::new();
    ignore_mgr.add_patterns(&args.ignore_pattern);

    for config in &args.ignore_config {
        ignore_mgr.add_from_file(config);
    }

    if args.gitignore {
        let curr_dir = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let gitignore_path = curr_dir.join(".gitignore");
        ignore_mgr.add_from_file(gitignore_path);
    }

    let ignore_matcher = match ignore_mgr.build_matcher() {
        Ok(m) => m,
        Err(e) => {
            eprintln!("Error building ignore matcher: {}", e);
            return 1;
        }
    };

    let fetched_transform = match resolve_transform_path(&args.transform) {
        Ok(ft) => ft,
        Err(err) => {
            eprintln!("Error resolving transform: {}", err);
            return 1;
        }
    };

    if !fetched_transform.path.exists() {
        let mut stderr = std::io::stderr();
        let _ = write!(
            stderr,
            "\x1b[41m\x1b[37mERROR\x1b[39m\x1b[49m Transform file {} does not exist \n",
            fetched_transform.path.to_string_lossy()
        );
        let _ = stderr.flush();
        return 0;
    }

    let files = get_all_files(paths, &args.extensions, &ignore_matcher);
    let num_files = files.len();

    if num_files == 0 {
        print!("No files selected, nothing to do. \n");
        let _ = std::io::stdout().flush();
        let elapsed = start_time.elapsed().as_secs_f64();
        if !args.silent {
            print!("All done. \n");
            print!("Results: \n");
            print!("\x1b[31m0 errors\n\x1b[39m");
            print!("\x1b[33m0 unmodified\n\x1b[39m");
            print!("\x1b[33m0 skipped\n\x1b[39m");
            print!("\x1b[32m0 ok\n\x1b[39m");
            print!("Time elapsed: {:.3}seconds \n", elapsed);
            let _ = std::io::stdout().flush();
        }
        return 0;
    }

    let available_cpus = std::cmp::max(num_cpus::get().saturating_sub(1), 1);
    let cpus = if let Some(c) = args.cpus {
        std::cmp::min(available_cpus, c)
    } else {
        available_cpus
    };

    let processes = if args.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };

    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, 50)
    } else {
        num_files
    };

    if !args.silent {
        print!("Processing {} files... \n", num_files);
        if !args.run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if args.dry {
            print!("\x1b[32mRunning in dry mode, no files will be written! \n\x1b[39m");
        }
        let _ = std::io::stdout().flush();
    }

    let files_arc = Arc::new(files);
    let next_index = Arc::new(Mutex::new(0usize));
    let state = Arc::new(Mutex::new(CounterState {
        error: 0,
        ok: 0,
        nochange: 0,
        skip: 0,
        stats: HashMap::new(),
    }));

    let options_json = serde_json::Value::Object(args.options.clone());

    let mut handles = Vec::new();

    for _ in 0..processes {
        let files_clone = Arc::clone(&files_arc);
        let next_idx_clone = Arc::clone(&next_index);
        let state_clone = Arc::clone(&state);
        let options_clone = options_json.clone();
        let transform_path = fetched_transform.path.clone();
        let babel = args.babel;
        let silent = args.silent;
        let run_in_band = args.run_in_band;
        let verbose = args.verbose;

        let handle = thread::spawn(move || {
            let mut worker = match spawn_worker(&transform_path, babel) {
                Ok(w) => w,
                Err(e) => {
                    eprintln!("Failed to spawn worker: {}", e);
                    let mut s = state_clone.lock().unwrap();
                    s.error += 1;
                    return;
                }
            };

            loop {
                let chunk = {
                    let mut idx = next_idx_clone.lock().unwrap();
                    let current = *idx;
                    if current >= files_clone.len() {
                        Vec::new()
                    } else {
                        let end = std::cmp::min(current + chunk_size, files_clone.len());
                        *idx = end;
                        let chunk_slice = &files_clone[current..end];
                        if !silent && !run_in_band {
                            print!("Sending {} files to free worker...\n", chunk_slice.len());
                            let _ = std::io::stdout().flush();
                        }
                        chunk_slice.to_vec()
                    }
                };

                if chunk.is_empty() {
                    let _ = worker.send_exit();
                    let _ = worker.child.wait();
                    break;
                }

                if worker.send_chunk(&chunk, &options_clone).is_err() {
                    break;
                }

                // Read output until free or exit
                let mut line = String::new();
                loop {
                    line.clear();
                    match worker.reader.read_line(&mut line) {
                        Ok(0) => break, // EOF
                        Ok(_) => {
                            let trimmed = line.trim();
                            if trimmed.starts_with('{') && trimmed.contains("\"_jscodeshift_ipc\":1") {
                                if let Ok(msg) = serde_json::from_str::<WorkerMessage>(trimmed) {
                                    if let Some(action) = msg.action.as_deref() {
                                        match action {
                                            "status" => {
                                                let status = msg.status.unwrap_or_default();
                                                let message = msg.msg.unwrap_or_default();
                                                {
                                                    let mut s = state_clone.lock().unwrap();
                                                    match status.as_str() {
                                                        "ok" => s.ok += 1,
                                                        "nochange" => s.nochange += 1,
                                                        "skip" => s.skip += 1,
                                                        "error" => s.error += 1,
                                                        _ => {}
                                                    }
                                                }
                                                log_status(&status, &message, verbose);
                                            }
                                            "update" => {
                                                if let (Some(name), Some(qty)) = (msg.name, msg.quantity) {
                                                    let mut s = state_clone.lock().unwrap();
                                                    *s.stats.entry(name).or_insert(0) += qty;
                                                }
                                            }
                                            "report" => {
                                                let file = msg.file.unwrap_or_default();
                                                let report_msg = msg.msg.unwrap_or_default();
                                                log_report(&file, &report_msg);
                                            }
                                            "free" => {
                                                break;
                                            }
                                            _ => {}
                                        }
                                    }
                                }
                            } else {
                                // stdout from user script
                                print!("{}", line);
                                let _ = std::io::stdout().flush();
                            }
                        }
                        Err(_) => break,
                    }
                }
            }
        });

        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start_time.elapsed().as_secs_f64();
    let final_state = state.lock().unwrap();

    if !args.silent {
        print!("All done. \n");
        print!("Results: \n");
        print!("\x1b[31m{} errors\n\x1b[39m", final_state.error);
        print!("\x1b[33m{} unmodified\n\x1b[39m", final_state.nochange);
        print!("\x1b[33m{} skipped\n\x1b[39m", final_state.skip);
        print!("\x1b[32m{} ok\n\x1b[39m", final_state.ok);

        if !final_state.stats.is_empty() {
            print!("\x1b[34mStats: \n\x1b[39m");
            let mut names: Vec<_> = final_state.stats.keys().collect();
            names.sort();
            for name in names {
                println!("{}: {}", name, final_state.stats[name]);
            }
        }

        print!("Time elapsed: {:.3}seconds \n", elapsed);
        let _ = std::io::stdout().flush();
    }

    if args.fail_on_error && final_state.error > 0 {
        1
    } else {
        0
    }
}
